import json
import math
import os
from urllib.error import HTTPError, URLError
from urllib.request import Request, urlopen

from langflow.custom import Component
from langflow.io import BoolInput, Output
from langflow.schema import Data


class DovaDataSource(Component):
    display_name = "Dova - Live FastAPI Context"
    description = "Ambil konteks operasional live dari FastAPI; FastAPI membaca Supabase."
    name = "DovaDataSource"

    inputs = [
        BoolInput(
            name="use_sample",
            display_name="Aktifkan sample (ditolak di flow LIVE)",
            value=False,
            info="Flow LIVE hanya menerima data dari endpoint FastAPI.",
        ),
    ]
    outputs = [Output(display_name="Data", name="result", method="run")]

    def run(self) -> Data:
        if self.use_sample:
            raise ValueError(
                "Flow LIVE tidak memakai sample. Gunakan flow FIXED SAFE untuk simulasi."
            )

        backend_url = os.getenv("DOVAGENOME_BACKEND_URL", "").strip().rstrip("/")
        if not backend_url:
            raise ValueError(
                "DOVAGENOME_BACKEND_URL belum dikonfigurasi pada proses Langflow."
            )
        token = os.getenv("DOVAGENOME_INTERNAL_TOKEN", "").strip()
        if not token:
            raise ValueError(
                "DOVAGENOME_INTERNAL_TOKEN belum dikonfigurasi pada proses Langflow."
            )

        raw_timeout = (
            os.getenv("DOVAGENOME_LIVE_TIMEOUT_SECONDS")
            or os.getenv("LANGFLOW_TIMEOUT_SECONDS")
            or ""
        ).strip()
        if not raw_timeout:
            raise ValueError(
                "DOVAGENOME_LIVE_TIMEOUT_SECONDS atau LANGFLOW_TIMEOUT_SECONDS belum dikonfigurasi pada proses Langflow."
            )
        try:
            timeout = float(raw_timeout)
        except ValueError as exc:
            raise ValueError("DOVAGENOME_LIVE_TIMEOUT_SECONDS invalid.") from exc
        if not math.isfinite(timeout) or timeout <= 0:
            raise ValueError("DOVAGENOME_LIVE_TIMEOUT_SECONDS harus positif.")
        # Live context aggregates can exceed the general Langflow client timeout.
        timeout = max(timeout, 120.0)

        request = Request(
            f"{backend_url}/api/ai/internal/context",
            headers={
                "Accept": "application/json",
                "X-Dova-Internal-Token": token,
            },
            method="GET",
        )
        try:
            with urlopen(request, timeout=timeout) as response:
                state = json.loads(response.read().decode("utf-8"))
        except HTTPError as exc:
            raise ValueError(
                f"FastAPI live context gagal HTTP {exc.code}."
            ) from exc
        except (URLError, TimeoutError, OSError) as exc:
            raise ValueError(
                "FastAPI live context tidak dapat dihubungi."
            ) from exc
        except (TypeError, ValueError, json.JSONDecodeError) as exc:
            raise ValueError(
                "FastAPI live context mengembalikan JSON yang tidak valid."
            ) from exc

        if not isinstance(state, dict):
            raise ValueError("FastAPI live context harus berupa object JSON.")
        if state.get("_data_mode") != "live":
            raise ValueError(
                "FastAPI tidak membuktikan _data_mode=live; flow dihentikan."
            )
        if state.get("_source") != "supabase_postgres_via_fastapi":
            raise ValueError(
                "Sumber live tidak terverifikasi sebagai Supabase via FastAPI."
            )

        counts = state.get("counts")
        if not isinstance(counts, dict):
            raise ValueError("FastAPI live context kehilangan counts; flow dihentikan.")
        for field in ("menus", "customers", "orders", "order_items", "stock_items", "suppliers"):
            value = counts.get(field)
            if isinstance(value, bool) or not isinstance(value, int) or value < 0:
                raise ValueError(f"FastAPI live context memiliki counts.{field} invalid; flow dihentikan.")
        self.status = (
            "live: "
            f"menus={counts['menus']}, "
            f"orders={counts['orders']}, "
            f"customers={counts['customers']}"
        )
        return Data(data=state)

