RESTRICTION_EXCLUDES = {
    "vegetarian": ["ayam", "chicken", "sapi", "beef", "daging", "seafood", "udang", "shrimp", "ikan", "fish", "cumi", "babi", "pork", "bacon", "kaldu ayam", "kaldu sapi"],
