}


def norm(s):
    return re.sub(r"\s+", " ", str(s or "").strip().lower())


def split_terms(x):
    if not x:
        return []
    if isinstance(x, str):
        x = x.replace(";", ",").split(",")
    return [norm(t) for t in x if norm(t)]


def has_word(text, kw):
    return re.search(r"(?<![a-z0-9])" + re.escape(kw) + r"(?![a-z0-9])", text) is not None


def canonical_allergen(term):
    t = norm(term)
    for name, d in ALLERGENS.items():
        if t == name or t in d["alias"]:
            return name
    return None


def match_ingredients(ingredients, keywords):
    return sorted({kw for ing in ingredients for kw in keywords if has_word(ing, kw)})


def check_one_menu(customer, menu_item):
    if not isinstance(menu_item, dict) or "ingredients" not in menu_item or not isinstance(menu_item["ingredients"], list):
        raise ValueError("LIVE menu kehilangan ingredients; dietary ditahan.")
    if "name" not in menu_item or not str(menu_item["name"]).strip():
        raise ValueError("LIVE menu kehilangan name; dietary ditahan.")
    ingredients = [norm(i) for i in menu_item["ingredients"]]
    tags = split_terms(menu_item.get("tags"))
    name = norm(menu_item["name"])
    haystack = ingredients + tags + [name]
    alerts = []

    def allergen_alerts(terms, kind, sev_direct, sev_possible):
        for term in terms:
            canon = canonical_allergen(term)
            if canon:
                d = ALLERGENS[canon]
                direct = match_ingredients(haystack, d["direct"])
                possible = [p for p in match_ingredients(haystack, d["possible"]) if p not in direct]
                if direct:
                    alerts.append({"type": kind, "allergen": canon, "severity": sev_direct, "confidence": "DIRECT",
                                   "matched": direct,
                                   "reason": f"Mengandung {', '.join(direct)} ({canon}): {d['reason']}."})
                if possible:
                    alerts.append({"type": kind, "allergen": canon, "severity": sev_possible, "confidence": "POSSIBLE",
                                   "matched": possible,
                                   "reason": f"Bahan {', '.join(possible)} mungkin mengandung {canon}; periksa label produk."})
            else:
                hit = match_ingredients(haystack, [term])
                if hit:
                    alerts.append({"type": kind, "allergen": term, "severity": sev_direct, "confidence": "LITERAL",
                                   "matched": hit, "reason": f"Mengandung {', '.join(hit)}."})

    required_customer_fields = ("allergy", "intolerance", "restriction", "dislike")
    if any(field not in customer for field in required_customer_fields):
        raise ValueError("LIVE customer dietary field tidak lengkap; dietary ditahan.")
    allergen_alerts(split_terms(customer["allergy"]), "allergy", "HIGH", "MEDIUM")
    allergen_alerts(split_terms(customer["intolerance"]), "intolerance", "MEDIUM", "LOW")

    for r in split_terms(customer["restriction"]):
        hit = match_ingredients(haystack, RESTRICTION_EXCLUDES.get(r, []))
        if hit:
            alerts.append({"type": "restriction:" + r, "severity": "HIGH", "confidence": "DIRECT",
                           "matched": hit, "reason": f"Tidak sesuai pantangan {r}: mengandung {', '.join(hit)}."})

    dislikes = split_terms(customer["dislike"])
    hit = match_ingredients(haystack, dislikes)
    if hit:
        alerts.append({"type": "dislike", "severity": "LOW", "confidence": "LITERAL",
                       "matched": hit, "reason": f"Mengandung {', '.join(hit)} yang kurang disukai."})

    if alerts:
        status = "WARNING"
    elif not ingredients:
        status = "DATA_INCOMPLETE"
    else:
        status = "NO_CONFLICT_DETECTED"
    return {"menu": menu_item["name"], "shown": True, "has_conflict": bool(alerts),
            "status": status, "alerts": alerts}


def check_dietary(customers, menu):
    out = []
    for c in customers:
        if not isinstance(c, dict) or "customer_id" not in c or "name" not in c:
            raise ValueError("LIVE customer identity tidak lengkap; dietary ditahan.")
        out.append({"customer_id": c["customer_id"], "name": c["name"],
                    "menu_check": [check_one_menu(c, m) for m in menu]})
    return out


def load_state(source, manual_json):
    state = {}
    if source is not None:
        d = source[0] if isinstance(source, list) else source
        state.update(getattr(d, "data", d) or {})
    if manual_json and str(manual_json).strip():
        raise ValueError("Flow LIVE menolak manual_json; gunakan endpoint FastAPI live.")
    return state


class DovaDietaryCheck(Component):
    display_name = "Dova · Dietary Check"
    description = "Cek alergi/intoleransi/pantangan/dislike vs menu memakai kamus alergen. Menu tetap tampil, konflik jadi alert."
    name = "DovaDietaryCheck"

    inputs = [
        DataInput(name="source", display_name="Data (dari node sebelumnya)", info="Sambungkan output node sebelumnya."),
        MultilineInput(name="manual_json", display_name="JSON manual (ditolak di LIVE)", advanced=True,
                       info="Flow LIVE hanya menerima data dari node upstream yang terverifikasi."),
    ]
    outputs = [Output(display_name="Data", name="result", method="run")]

    def run(self) -> Data:
        state = load_state(self.source, self.manual_json)
        if "customers" not in state or "menu" not in state:
            raise ValueError("LIVE context kehilangan customers/menu; dietary ditahan.")
        if not isinstance(state["customers"], list) or not isinstance(state["menu"], list):
            raise ValueError("LIVE context memiliki customers/menu invalid; dietary ditahan.")
        state["dietary"] = check_dietary(state["customers"], state["menu"])
        self.status = state.get("_status", "ok")
        return Data(data=state)

import json
import math
from collections import defaultdict
from datetime import date, datetime, timedelta

from langflow.custom import Component
from langflow.io import DataInput, IntInput, MultilineInput, DropdownInput, Output
from langflow.schema import Data

def to_date(v):
    if isinstance(v, datetime):
        return v.date()
    if isinstance(v, date):
        return v
    return datetime.fromisoformat(str(v)[:10]).date()

def required_order_value(order, field):
    if field not in order or order[field] is None:
        raise ValueError(f"LIVE order kehilangan {field}; CRM/RFM ditahan.")
    return order[field]

def group_orders(orders):
    """Gabungkan baris order (per menu) menjadi order per customer."""
    tmp = defaultdict(lambda: defaultdict(lambda: {"qty": 0, "total": 0.0, "date": None}))
    names = {}
    for o in orders:
        cid = required_order_value(o, "customer_id")
        order_id = required_order_value(o, "order_id")
        order_date = required_order_value(o, "order_date")
        quantity = required_order_value(o, "quantity")
        total = required_order_value(o, "total")
        menu = required_order_value(o, "menu")
        customer_name = required_order_value(o, "customer_name")
        if isinstance(quantity, bool) or not isinstance(quantity, (int, float)) or quantity < 0:
            raise ValueError("LIVE order memiliki quantity invalid; CRM/RFM ditahan.")
        if isinstance(total, bool) or not isinstance(total, (int, float)) or total < 0:
            raise ValueError("LIVE order memiliki total invalid; CRM/RFM ditahan.")
        if not str(customer_name).strip() or not str(menu).strip():
            raise ValueError("LIVE order memiliki customer/menu kosong; CRM/RFM ditahan.")
        key = str(order_id)
        t = tmp[cid][key]
        t["qty"] += quantity
        t["total"] += total
        t["date"] = to_date(order_date)
        names[cid] = str(customer_name)
    grouped = {cid: sorted(v.values(), key=lambda r: r["date"]) for cid, v in tmp.items()}
    return grouped, names

def build_crm_profiles(orders):
    grouped, names = group_orders(orders)
    menu_qty = defaultdict(lambda: defaultdict(int))
    for o in orders:
        cid = required_order_value(o, "customer_id")
        menu = required_order_value(o, "menu")
        quantity = required_order_value(o, "quantity")
        if isinstance(quantity, bool) or not isinstance(quantity, (int, float)) or quantity < 0:
            raise ValueError("LIVE order memiliki quantity invalid; CRM ditahan.")
        menu_qty[cid][menu] += quantity
    profiles = {}
    for cid, rows in grouped.items():
        dates = [r["date"] for r in rows]
        gaps = [(b - a).days for a, b in zip(dates, dates[1:])]
        prefs = sorted(menu_qty[cid].items(), key=lambda kv: -kv[1])
        profiles[cid] = {
            "customer_name": names[cid],
            "order_count": len(rows),
            "avg_quantity": round(sum(r["qty"] for r in rows) / len(rows), 1),
            "avg_spending": round(sum(r["total"] for r in rows) / len(rows)),
            "reorder_interval_days": round(sum(gaps) / len(gaps), 1) if gaps else None,
            "favorite_menu": prefs[0][0] if prefs else None,
            "menu_preference": [{"menu": m, "qty": q} for m, q in prefs],
            "last_order_date": str(dates[-1]),
        }
    return profiles


def load_state(source, manual_json):
    """Gabungkan Data dari node sebelumnya + (opsional) JSON manual."""
    state = {}
    if source is not None:
        d = source[0] if isinstance(source, list) else source
        state.update(getattr(d, "data", d) or {})
    if manual_json and str(manual_json).strip():
        raise ValueError("Flow LIVE menolak manual_json; gunakan endpoint FastAPI live.")
    return state


class DovaCRMProfile(Component):
    display_name = "Dova · CRM Profile"
    description = "Bentuk profil customer dari histori order: frekuensi, rata-rata belanja, interval reorder, menu favorit."
    name = "DovaCRMProfile"

    inputs = [
        DataInput(name="source", display_name="Data (dari node sebelumnya)", info="Sambungkan output node sebelumnya."),
        MultilineInput(name="manual_json", display_name="JSON manual (ditolak di LIVE)", advanced=True,
                       info="Flow LIVE hanya menerima data dari node upstream yang terverifikasi."),
    ]
    outputs = [Output(display_name="Data", name="result", method="run")]

    def run(self) -> Data:
        state = load_state(self.source, self.manual_json)
        state["crm_profiles"] = build_crm_profiles(state["orders"])
        self.status = state.get("_status", "ok")
        return Data(data=state)

