def quintile_scores(values, higher_is_better=True):
    n = len(values)
    out = []
    for v in values:
        c = sum(1 for x in values if (x <= v if higher_is_better else x >= v))
        out.append(max(1, min(5, math.ceil(5 * c / n))))
    return out

def rfm_segment(r, f, recency_days, at_risk_days, churn_days):
    if recency_days > churn_days:
        return "CHURNED"
    if recency_days > at_risk_days and f >= 2:
        return "AT_RISK"
    if r >= 4 and f >= 4:
        return "CHAMPION"
    if f >= 3 and r >= 3:
        return "LOYAL"
    if r >= 4 and f <= 2:
        return "NEW_OR_PROMISING"
    return "REGULAR"

def compute_rfm(orders, today=None, at_risk_days=14, churn_days=30):
    if today is None:
        raise ValueError("LIVE context kehilangan today; RFM ditahan.")
    today = to_date(today)
    grouped, names = group_orders(orders)
    ids = list(grouped)
    if not ids:
        return []
    rec = [(today - grouped[c][-1]["date"]).days for c in ids]
    freq = [len(grouped[c]) for c in ids]
    mon = [sum(r["total"] for r in grouped[c]) for c in ids]
    rs = quintile_scores(rec, higher_is_better=False)
    fs = quintile_scores(freq)
    ms = quintile_scores(mon)
    rows = []
    for i, c in enumerate(ids):
        rows.append({
            "customer_id": c, "customer_name": names[c],
            "recency_days": rec[i], "frequency": freq[i], "monetary": round(mon[i]),
            "R": rs[i], "F": fs[i], "M": ms[i], "rfm_score": f"{rs[i]}{fs[i]}{ms[i]}",
            "segment": rfm_segment(rs[i], fs[i], rec[i], at_risk_days, churn_days),
            "n_customers_in_scoring": len(ids),
        })
    return sorted(rows, key=lambda r: r["customer_id"])


