def _strict_quantity(row):
    if not isinstance(row, dict) or "quantity" not in row:
        raise ValueError("Forecast live memiliki quantity yang hilang; output ditahan.")
    try:
        quantity = float(row["quantity"])
    except (TypeError, ValueError) as exc:
        raise ValueError("Forecast live memiliki quantity yang tidak valid; output ditahan.") from exc
    if not math.isfinite(quantity) or quantity < 0:
        raise ValueError("Forecast live memiliki quantity non-finite/negatif; output ditahan.")
    unit = str(row.get("unit") or "").strip()
    if not unit:
        raise ValueError("Forecast live memiliki unit yang hilang; output ditahan.")
    return quantity, unit


def report_to_items(report):
    if not isinstance(report, dict):
        raise ValueError("Forecast backtest live tidak tersedia.")
    if report.get("data_mode") != "live" or report.get("source") != "supabase_postgres":
        raise ValueError("Forecast bukan report live Supabase yang terverifikasi.")
    if report.get("calculation_version") != "forecast_backtest_v2":
        raise ValueError("Versi forecast tidak sesuai kontrak v2; output ditahan.")
    status = report.get("status")
    if not isinstance(status, str) or not status.strip():
        raise ValueError("Forecast live kehilangan status; output ditahan.")
    status = status.strip()
    items = []
    # Forecast non-OK (misalnya STALE_DATA) is deliberately not converted
    # into operational portions or inventory demand.
    warnings = report.get("warnings")
    if not isinstance(warnings, list):
        raise ValueError("Forecast live memiliki warnings invalid; output ditahan.")
    warnings = report.get("warnings")
    if not isinstance(warnings, list):
        raise ValueError("Forecast live memiliki warnings invalid; output ditahan.")
    if status == "OK":
        series_rows = report.get("series")
        if not isinstance(series_rows, list):
            raise ValueError("Forecast live kehilangan series; output ditahan.")
        for series in series_rows:
            if not isinstance(series, dict):
                raise ValueError("Forecast live memiliki series yang tidak valid.")
            rows = series.get("forecast")
            if not isinstance(rows, list):
                raise ValueError("Forecast live memiliki daftar forecast yang tidak valid.")
            if not rows:
                continue
            if "unit" not in series or "label" not in series or "series_key" not in series:
                raise ValueError("Forecast live kehilangan identitas series/unit.")
            series_unit = str(series["unit"]).strip()
            menu = str(series["label"]).strip()
            if not series_unit or not menu or not str(series["series_key"]).strip():
                raise ValueError("Forecast live memiliki identitas series/unit yang hilang.")
            quantity = 0.0
            for row in rows:
                row_quantity, row_unit = _strict_quantity(row)
                if row_unit != series_unit:
                    raise ValueError("Forecast live memiliki unit campuran dalam satu series.")
                quantity += row_quantity
            method = rows[0].get("method")
            if not isinstance(method, str) or not method.strip():
                raise ValueError("Forecast live kehilangan method; output ditahan.")
            items.append({
                "menu": menu,
                "forecast_portions": round(quantity, 2),
                "unit": series_unit,
                "method": method,
            })
    return {
        "status": status,
        "forecast_status": status,
        "horizon_days": report.get("horizon_days"),
        "data_age_days": report.get("data_age_days"),
        "items": items,
        "source": report.get("source"),
        "calculation_version": report.get("calculation_version"),
        "data_mode": report.get("data_mode"),
        "warnings": warnings,
    }


def load_state(source, manual_json):
    state = {}
    if source is not None:
        d = source[0] if isinstance(source, list) else source
        state.update(getattr(d, "data", d) or {})
    if manual_json and str(manual_json).strip():
        raise ValueError("Flow LIVE menolak manual_json; gunakan endpoint FastAPI live.")
    return state


