def build_summary(s):
    L = ["# Ringkasan Dova Kitchen", ""]
    mode = s.get("_data_mode")
    source = s.get("_source")
    counts = s.get("counts")
    if not isinstance(mode, str) or not mode.strip() or not isinstance(source, str) or not source.strip():
        raise ValueError("Summary kehilangan provenance; output ditahan.")
    if not isinstance(counts, dict):
        raise ValueError("Summary kehilangan counts; output ditahan.")
    required_counts = ("menus", "customers", "orders", "stock_items", "suppliers")
    if any(field not in counts or isinstance(counts[field], bool) or not isinstance(counts[field], int) or counts[field] < 0 for field in required_counts):
        raise ValueError("Summary memiliki counts invalid; output ditahan.")
    L += [
        "## Data provenance",
        f"- Mode data: {mode}",
        f"- Sumber data: {source}",
    ]
    if counts:
        L += [
            f"- Menu: {counts['menus']}",
            f"- Customer: {counts['customers']}",
            f"- Order: {counts['orders']}",
            f"- Stok: {counts['stock_items']}",
            f"- Supplier: {counts['suppliers']}",
        ]
    warnings = s.get("warnings")
    if not isinstance(warnings, list):
        raise ValueError("Summary memiliki warnings invalid; output ditahan.")
    for warning in warnings:
        L.append(f"- Warning: {warning}")
    L.append("")
    customer_mode = s.get("_audience") == "customer"
    if customer_mode:
        menu_rows = s.get("menu")
        customer_rows = s.get("customers")
        if not isinstance(menu_rows, list) or not isinstance(customer_rows, list):
            raise ValueError("Summary kehilangan menu/customers; output ditahan.")
        L.append("## Menu yang tersedia")
        for m in menu_rows:
            L.append(f"- {m.get('name')}: bahan = {', '.join(m.get('ingredients', []))}")
        L.append("")
        if not customer_rows:
            L.append("Profil pelanggan belum ditemukan. Jangan menyebut data pribadi; sarankan login atau isi profil alergi di aplikasi.")
    if "dietary" in s:
        L.append("## Cek dietary (menu tetap ditampilkan, konflik jadi peringatan)")
        for c in s["dietary"]:
            conf = [m for m in c["menu_check"] if m["has_conflict"]]
            incomplete = [m["menu"] for m in c["menu_check"] if m.get("status") == "DATA_INCOMPLETE"]
            if not conf:
                L.append(f"- {c['name']}: tidak ada konflik terdeteksi pada data bahan yang tersedia (ini bukan jaminan aman)")
            for m in conf:
                al = "; ".join(f"{a['type']} [{a['severity']}] {a.get('reason') or ', '.join(a['matched'])}" for a in m["alerts"])
                L.append(f"- {c['name']} -> {m['menu']}: PERINGATAN {al}")
            for n in incomplete:
                L.append(f"- {c['name']} -> {n}: DATA BAHAN TIDAK LENGKAP, tidak bisa diperiksa")
    if "crm_profiles" in s:
        L += ["", "## Profil customer (CRM)"]
        for cid, p in s["crm_profiles"].items():
            L.append(f"- {p['customer_name']} ({cid}): {p['order_count']} order, rata-rata Rp{p['avg_spending']:,}, interval reorder {p['reorder_interval_days']} hari, favorit {p['favorite_menu']}")
        L.append("")
    if "rfm" in s:
        L.append("## Segmen customer (RFM)")
        for r in s["rfm"]:
            L.append(f"- {r['customer_name']}: {r['segment']} (RFM {r['rfm_score']}, terakhir order {r['recency_days']} hari lalu)")
    forecast_rows = s.get("forecast")
    if not isinstance(forecast_rows, dict):
        raise ValueError("Summary kehilangan forecast; output ditahan.")
    for k, f in forecast_rows.items():
        L += ["", f"## Forecast {k} [{f['status']}]"]
        L += [f"- {i['menu']}: {i['forecast_portions']} porsi" for i in f["items"]]
    if "inventory" in s:
        L += ["", "## Inventory"]
        L += [f"- {i['ingredient']}: {i['status']} (kurang {i['shortage_kg']} kg)" for i in s["inventory"]["ingredients"]]
    if "purchase_orders" in s:
        L += ["", "## Draft PO (menunggu approval admin)"]
        for po in s["purchase_orders"]["purchase_orders"]:
            L.append(f"- {po['supplier']}: Rp{po['est_total']:,} -> " + ", ".join(f"{l['ingredient']} {l['qty_kg']}kg" for l in po["lines"]))
        L += [f"- TANPA SUPPLIER: {u['ingredient']}" for u in s["purchase_orders"]["unresolved"]]
    if "marketing" in s:
        L += ["", "## Draft marketing (belum dikirim)"]
        L += [f"- [{m['action']}] {m['message']}" for m in s["marketing"]]
    return "\n".join(L)


class DovaSummary(Component):
    display_name = "Dova · Summary"
    description = "Ubah hasil pipeline jadi teks ringkas untuk Prompt Template."
    name = "DovaSummary"

    inputs = [DataInput(name="source", display_name="Data")]
